import { spawn } from 'node:child_process';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: ':memory:' },
  stdio: ['ignore', 'pipe', 'pipe'],
  detached: true,
});
let output = '';
const timeout = setTimeout(() => process.kill(-child.pid, 'SIGTERM'), 10000);
try {
  const port = await new Promise((resolve, reject) => {
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = /listening on port (\d+)/.exec(output);
      if (match) resolve(match[1]);
    });
    child.on('error', reject);
    child.on('exit', (code) => reject(new Error(`npm start exited ${code}`)));
  });
  const response = await fetch(`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
  console.log('npm start and /health passed');
} finally {
  clearTimeout(timeout);
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
}
EOF","max_output_tokens":1000}));

